    'RegistrationText'=>'Бүртгүүлсэн SimpleRisk instance-үүд Upgrade болон Secure Controls Framework (SCF) Extra-уудад хандах хандалтыг шууд авна.  Upgrade Extra нь SimpleRisk instance-ээ нэг товшилтоор нөөцлөх болон шинэчлэх боломжийг олгодог.  Secure Controls Framework (SCF) Extra нь SimpleRisk-ийн засаглалын функцэд нэгтгэгдсэн нийтлэг хяналтын framework-ийг хангадаг.  SimpleRisk-д бүртгүүлснээр таны бүртгэлийн мэдээлэл SimpleRisk-ийн хостолсон сервер рүү илгээгдэнэ.  Өгсөн бүртгэлийн мэдээллийг SimpleRisk нь шинэ хувилбар болон аюулгүй байдлын шинэчлэлтийн талаар үйлчлүүлэгчдэд мэдэгдэхэд ашиглана.  SimpleRisk-д бүртгүүлснээр та манай маркетингийн харилцаанд хамрагдах бөгөөд эдгээр харилцаан дахь цуцлах холбоосоор хүссэн үедээ татгалзаж болно.  SimpleRisk нь үйлчлүүлэгчдийнхээ нууцлалыг хүндэтгэдэг бөгөөд SimpleRisk-ийн бүртгэлийн явцад бидэнд өгсөн мэдээллийг гуравдагч этгээдэд хэзээ ч зарахгүй.',
