    'ExtrasDesc'                          => 'SimpleRisk Extra-уудыг (төлбөртэй нэмэлт модулиуд) идэвхжүүлэх, идэвхгүй болгох болон тохируулах.',
    'ArtificialIntelligenceExtraDesc'     => 'Хиймэл Оюун Ухааны Нэмэлт нь сайжруулсан эрсдэлийн шинжилгээ (FAIR үнэлгээг оруулаад) болон захиалгат баримтжуулалтыг өгдөг.',
    'CustomizationExtraDesc'              => 'Тохируулгын нэмэлт нь янз бүрийн төрлийн талбаруудыг нэмэх, хасах, мөн өөрчлөн тохируулсан хуудасны загваруудыг динамикаар үүсгэх боломжийг олгодог.',
    'NotificationExtraDesc'               => 'Имэйл Мэдэгдэл Нэмэлт нь эрсдэлийг илгээх, өөрчлөх эсвэл өөр арга хэмжээ авах үед SimpleRisk-д имэйл мэдэгдэл илгээх боломжийг олгодог. Энэхүү нэмэлтийг мөн эрсдэлийг удирдлагын хяналтад бэлэн болсон үед тогтмол сануулга илгээх хуваарьт скрипт болгон нэмж болно. SimpleRisk Core бүтээгдэхүүнд энэхүү Нэмэлтгүйгээр ямар ч мэдэгдэл хэрэгслээс өөрөөс нь гадуур дамжуулагдахгүй.',
    'VulnerabilityManagementExtraDesc'    => 'Эмзэг байдлын менежментийн нэмэлт нь үйлчлүүлэгчдэд SimpleRisk инстансаа Qualys, Tenable.io эсвэл Rapid7 Nexpose/InsightVM-тэй нэгтгэж, хөрөнгө болон эмзэг байдлын өгөгдлийг хоёуланг нь SimpleRisk руу импортлох боломжийг олгодог. Тэндээс та аль сайтуудыг хамрахыг хүсч байгаагаа сонгож, ямар эмзэг байдлын оноог импортлох ёстойгоо тодорхойлж, аль эмзэг байдлыг эрсдэл болгон хувиргаж байгааг нь ангилж, тэдгээрийг хянах боломжтой.',
    'IncidentManagementExtraDesc'         => 'Осол хэргийн удирдлагын Extra нь NIST 800-61 Компьютерийн аюулгүй байдлын осол хэрэгтэй ажиллах гарын авлагад суурилсан бөгөөд SimpleRisk системийн дотор осол хэргийг удирдах чадамжийг хангана.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'SimpleRisk-ийн нэр томьёог (Эрсдэл, Хөрөнгө, Framework гэх мэт) UI даяар өөрчлөх.',
    'RiskConfigurationDesc'               => 'Эрсдэлийн онооны дүрмийг тохируулах: түвшин, эрсдэл хүлээн авах хэмжээ, SLA босго болон сонгодог / хувь нэмэр оруулдаг эрсдэлийн томъёо.',
    'RiskAndThreatCatalogDesc'            => 'Унжих жагсаалтад ашигласан эрсдэл ба аюулын утгуудын каталогийг хөтлөх.',
    'AddAndRemoveValuesDesc'              => 'Эрсдэлийн талбаруудын унах цэсний утгыг удирдах: байршил, эх үүсвэр, ангилал, баг, технологи гэх мэт.',
    'AssetValuationDesc'                  => 'Хөрөнгийн үнэлгээний хуваарь болон хөрөнгө тус бүрийн үнэлгээний давхарлан тохируулгыг тохируулах.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Хэрэглэгчдийг нэмэх, засварлах, идэвхгүй болгох, шинэчлэн тохируулах; нууц үгийн бодлогыг удирдах.',
    'RoleManagementDesc'                  => 'Үүрэг болон үүрэг тус бүрийн олгох зөвшөөрлийг тодорхойлох.',
    'TeamManagementDesc'                  => 'Бичлэгийн харагдах байдлыг шүүхэд ашигладаг багийг үүсгэж, удирдах.',
    'SeparationExtraDesc'                 => 'Багт суурилсан тусгаарлах нэмэлт нь эрсдэлийг зөвхөн эрсдэл оноогдсон багийн гишүүд болох хэрэглэгчдэд л харах боломжийг олгодог. SimpleRisk Core бүтээгдэхүүнд энэхүү нэмэлтгүйгээр хэрэглэгч бүр эрсдэл бүрийг харж чадна.',
    'CustomAuthenticationExtraDesc'       => 'Тусгай нэвтрэлт баталгаажуулалтын Extra нь Active Directory болон SAML нэвтрэлт баталгаажуулалтыг дэмжинэ. SimpleRisk Core бүтээгдэхүүнд энэ Extra байхгүй бол цорын ганц сонголт нь SimpleRisk-ийн хэрэглэгчийн нэрсийн сан дотор шинэ хэрэглэгч үүсгэх явдал юм.',
    'EncryptionExtraDesc'                 => 'Шифрлэгдсэн мэдээллийн сангийн нэмэлт нь санамсаргүй AES-256 битийн шифрлэлтийн түлхүүр үүсгэж, дараа нь SimpleRisk мэдээллийн санд оруулахаас өмнө нууц текстийг шифрлэхэд ашигладаг. Энэ нь SimpleRisk програмыг шууд ашиглахгүйгээр хэн ч өгөгдлийг харах эсвэл өөрчлөх боломжгүй болгодог.',
    'OrganizationManagementDesc'          => "Байгууллагын шатлалын нэмэлт нь олон тооны багуудыг багтааж болох олон бизнесийн нэгжийг тодорхойлох боломжийг олгодог. Дараа нь хэрэглэгчдийг янз бүрийн бизнесийн нэгжүүдийн дор нэг буюу хэд хэдэн багт хуваарилж болно. Энэ нь хэрэглэгчийн өөрсдөд нь хамааралгүй багууд, хэрэглэгчид болон хөрөнгийг харах, ашиглах чадварт нөлөөлдөг.",

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Эрсдэлүүдийг бөөнөөр устгах. Болгоомжтой ашиглана уу — устгалтыг буцаах боломжгүй.',
    'AuditTrailDesc'                      => 'Хэрэглэгчийн үйлдлийн системийн аудитын бүртгэлийг хайж, экспортлох.',
    'ImportExportExtraDesc'               => 'Импорт-экспортын Extra нь CSV файлын талбаруудыг SimpleRisk мэдээллийн сангийн талбаруудтай зураглан өгөгдлийг SimpleRisk руу импортлох боломжийг олгоно. Үүгээр гуравдагч этгээдийн хүснэгтээс аудитын үр дүн, өөр хэрэгслийн эмзэг байдлын сканы үр дүн, CMDB-ээс хөрөнгө болон бусдыг импортлож болно. Мөн Extra нь SimpleRisk-ээс эрсдэл, бууруулах арга хэмжээ, хяналтын үнэлгээ эсвэл гурвын нэгдсэн тайлан агуулсан CSV файлуудыг экспортлох боломжийг олгоно.',
    'JiraExtraDesc'                       => 'Jira Integration Extra нь хэрэглэгчдэд Jira инстанцтай хоёр чиглэлт нэгтгэх боломжийг олгодог. Энэ нь эрсдэлийг Jira-ийн асуудлуудтай холбох, мөн тэдний өгөгдөл, төлөв байдал, сэтгэгдлийг синхрончлох боломжийг олгодог.',
    'APIExtraDesc'                        => 'API Extra нь хэрэглэгчдэд RESTful API ашиглан бусад програмуудтай скриптэд суурилсан харилцан үйлдэл үүсгэж, дэвшилтэт автоматжуулалт хийх болон одоо байгаа дэд бүтцээ ашиглах боломжийг олгоно.',
    'AdvancedSearchExtraDesc'             => "Дэвшилтэт хайлтын нэмэлт нь дээд мөрийн хайлтын хайрцгийг эрсдэл, хүрээ, хяналт, баримт бичиг, үл хамаарах зүйлс, тест, аудит, хөрөнгө болон хөрөнгийн бүлгүүдийн нэг хайлт болгон хувиргадаг бөгөөд үр дүнг харах бүрэн хайлтын хуудастай. Энэ нь зөвхөн хэрэглэгчийн харахыг зөвшөөрсөн бүртгэлийг харуулдаг.",
    'AssessmentsExtraDesc'                => 'Эрсдэлийн үнэлгээний нэмэлт нь хэрэглэгчдэд холбоо барих хүмүүсийг тодорхойлох, асуулт үүсгэх (логикийг оролцуулан), асуулгын загвараар олон асуултыг нэгтгэх, асуулгын хуудас үүсгэж, холбоо барих хүмүүст илгээх, асуулгын үр дүнг харах, тэдгээр үр дүнд үндэслэн эрсдэл нэмэх, үр дүнг цаг хугацааны явцад харьцуулах, гаднаас тохируулсан үнэлгээг импортлох, экспортлох, эрсдэлийн үнэлгээний аудитын мөрийг хянах боломжийг олгодог.',
    'ActiveAssessmentsDesc'               => 'Одоогоор үргэлжилж буй үнэлгээнүүдийг харах болон удирдах.',
    'WorkflowsExtraDesc'                  => 'Ажлын урсгалын Extra нь SimpleRisk доторх үйл явдлуудад хариу болгон эрсдэлийн удирдлагын үйлдлүүдийг автоматжуулдаг, үзэгдэхүйц, үйл явдалд суурилсан ажлын урсгалын хөдөлгүүрийг хангана. Та эрсдэлийг илгээх, шинэчлэх эсвэл хянах зэрэг өөрчлөлтөд идэвхжих ажлын урсгалыг зохиож, зөвшөөрөл дамжуулах, ажил оноох, процессоо гараар оролцохгүйгээр урагшлуулах боломжтой.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => "Secure Controls Framework (SCF) Extra нь Secure Controls Framework болон SimpleRisk-ийн шууд интеграцчилал юм. Энэ нь SCF-ийн хяналтын каталог болон тэдгээрийн өргөн хүрээний нийцэл болон кибер аюулгүй байдлын хүрээнд хийсэн зураглалыг SimpleRisk-ийн Засаглалын функцэд импортолдог тул та хэрэгтэй фрэймворкуудыг гараар бүтээхгүйгээр ашиглаж, тэдгээрийн хяналтыг удирдах боломжтой.",

