    'EncryptionMissingLockTablesPrivilegeUi' => 'SimpleRisk мэдээллийн сангийн хэрэглэгч нь шифрлэлтэд шаардлагатай LOCK TABLES эрхгүй байна. Мэдээллийн сангийн администратор дараахыг ажиллуулах ёстой: GRANT LOCK TABLES ON {$db}.* TO {$user}; дараа нь дахин оролдоно уу.',
