    'SoaLegendEvidenceFail' => 'Энэ хяналтын тест сүүлд ажилласан үедээ унасан гэж бүртгэсэн. Хавсралт R-д эмчилгээний төлөвлөгөө байгаа бол оруулсан болно.',
    'SoaLegendEvidenceInconclusive' => 'Энэ хяналтын тест ажилласан боловч дүгнэлт гараагүй. Энэ баримт бичгээс танихгүй үр дүнд мөн адил тэмдэг ашигладаг бөгөөд тэр тохиолдолд үр дүнг нь хажууд нь хэвлэнэ.',
    // The TERM beside the § glyph. Not a document type -- the four types
