    'SoaEvidenceDesignDocument' => 'Дизайны баримт бичиг',
    'SoaLegendEvidenceDocument' => 'Энэ хяналтын нотлох баримтаар баталгаажсан засаглалын баримт бичиг — үйл ажиллагааг нь бус зохиомжийг нь харуулна. Баримт бичиг дүгнэлт агуулдаггүй тул ✓ тэмдгээр тэмдэглэдэггүй.',
    // The XLSX export's first worksheet tab. The workbook's other four tabs reuse
    // headings that already exist ('How to read this statement', 'Statement of
